\section{Proof of Main Results}
\label{app:proof}
\begin{definition}[Window]
    Let $M\in\mathbb{N}_{\geq 1}$ and $W_M:=\{-M,...,M\}$. A function $p:W_M\to[0,1]$ is called window if $\sum_{m\in W_M}p(m)=1$.
\end{definition}
\begin{definition}[Admissible window]
    \label{def:admissible_app}
    Let $M\in \mathbb{N}_{\geq 1}$, let $\sigma\geq 1$, $b\in(0,1]$, and $C,C',C'',C'''>0$ be constants independent of $M$, and set $T:=\max(1,M/\sigma)$. A window $p$ on $W_M$ is called $(b,\sigma, C, C',C'',C''')$-admissible if 
    \begin{enumerate}
        \item[(W1)] $p(m)+p(-m)\geq \frac{b}{T}$ for all $m\in W_M$ with $1\leq m \leq T$, and
        \item[(W2)] $\mathbb{E}[m^2]\leq CT^2$, $\mathbb{E}[m^4]\leq C'T^4$, $\mathbb{E}[m^6]\leq C''T^6$, and $\mathbb{E}[m^8]\leq C'''T^8$
    \end{enumerate}
\end{definition}
\begin{remark}
\label{remark:definitions}
\Cref{def:admissible_app} refines \cref{def:admissible} of the main text: condition (W1) is identical, while (W2) makes the moment bounds explicit so that we can track constant factors. Condition (W2) imposes no additional restriction. In particular, every window on $W_M$ is supported on $|m| \leq M \leq  \sigma T$, so $\mathbb{E}[m^{2k}] \leq \sigma^{2k} T^{2k}$ for every $k$, and hence every $(b,\sigma)$-admissible window is $(b,\sigma,\sigma^2,\sigma^4,\sigma^6,\sigma^8)$-admissible. Conversely, every $(b,\sigma,C,C',C'',C''')$-admissible window is $(b,\sigma)$-admissible by (W1). The two definitions therefore describe the same class of windows, and every statement below applies verbatim to a $(b,\sigma)$-admissible window with $C = \sigma^2$, $C' = \sigma^4$, $C'' = \sigma^6$, $C''' = \sigma^8$.
\end{remark}

\begin{definition}[optimal loss]
    Let $p$ be a window and $\lambda\in [0,\pi/2]$. The optimal loss $\mathcal{E}^{(\lambda)}:[0,\pi/2]\to [0,4]$ is defined via
    \begin{equation}
        \mathcal{E}^{(\lambda)}(\theta)=\mathbb{E}_{m\sim p}\left[\mathcal{E}^{(\lambda)}_m(\theta) \right],\qquad\mathcal{E}_m^{(\lambda)}(\theta)= (\cos(2m\lambda)-\cos(2m\theta))^2.
    \end{equation}
\end{definition}

\begin{definition}[empirical loss]
    \label{def:empirical_loss}
    Let $p$ be a window, $\lambda\in [0,\pi/2]$, and $N\in\mathbb{N}_{\geq 1}$. For $m\in W_M$, define $p^{(\lambda)}_{m}:\{-1,1\}\to[0,1]$ via $p^{(\lambda)}_m(-1)=\sin^2(m\lambda)$ and $p^{(\lambda)}_m(1)=\cos^2(m\lambda)$. Given $N$ i.i.d.\ draws $\left(m_i,Z_{i} \right)$ with $m_i\sim p$ and, conditional on $m_i$, $Z_{i}\sim p^{(\lambda)}_{m_i}$, define the empirical loss $L^{(\lambda)}_N:[0,\pi/2]\to [0,4]$ via
    \begin{equation}
        L^{(\lambda)}_N(\theta)=\frac{1}{N}\sum_{i=1}^N\left(Z_{i}-\cos(2m_i\theta)\right)^2.
    \end{equation}
    Furthermore, define the empirical fluctuation as $D^{(\lambda)}_N(\theta):=L^{(\lambda)}_N(\theta)-L^{(\lambda)}_N(\lambda)-\mathcal{E}^{(\lambda)}(\theta)$.
\end{definition}

\begin{definition}[uniform grid]
    \label{def:uniform_grid}
    For $K\in\mathbb{N}_{\geq1}$, let $\kappa:=\frac{\pi}{2K}$ and define the uniform grid of spacing
    $\kappa$ with $K$ grid points as
    $G_K:=\{(j+\frac{1}{2})\kappa:0\leq j< K\}\subset[0,\pi/2]$. 
\end{definition}

\begin{remark}
    A few remarks are in order:
    \begin{enumerate}
        \item[(R1)] It is $\mathbb{E}_{Z_m\sim p_m^{(\lambda)}}[Z_m]=\cos(2m\lambda)$ and $\mathrm{Var}_{Z_m\sim p_m^{(\lambda)}}[Z_m]=\sin^2(2m\lambda)$.
        \item[(R2)] The covering radius of a uniform grid $G_K$ with $\kappa=\frac{\pi}{2K}$ is $\kappa/2$: for every $\lambda\in[0,\pi/2]$ there exists a $\theta\in G_K$  with $|\theta-\lambda|\leq\kappa/2$.
    \end{enumerate}
\end{remark}

\begin{proposition}
    Let $p$ be a window, $\lambda\in [0,\pi/2]$, and $N\in\mathbb{N}_{\geq 1}$. Then, for every $\theta\in[0,\pi/2]$, we have
    \begin{equation}
        \mathbb{E}\left[L^{(\lambda)}_N(\theta)-L^{(\lambda)}_N(\lambda)\right]=\mathcal{E}^{(\lambda)}(\theta),
    \end{equation}
    which implies $\mathbb{E}[D^{(\lambda)}_N(\theta)]=0$.
\end{proposition}
\begin{proof}
    It is 
    \begin{equation}
        (Z_{i}-\cos(2m_i\phi))^2=1-2Z_{i}\cos(2m_i\phi)+\cos^2(2m_i\phi),
    \end{equation}
    and, from (R1), we know that $\mathbb{E}_{Z_{i}\sim p_{m_i}^{(\lambda)}}\left[Z_{i}\right]=\cos(2m_i\lambda)$. It follows
    \begin{align}
        \label{eq:prop_1}
        \mathbb{E}_{Z_{i}\sim p_{m_i}^{(\lambda)}}\left[ (Z_{i}-\cos(2m_i\phi))^2 \right] = 1-2\cos(2m_i\lambda) \cos(2m_i\phi)+\cos^2(2m_i\phi).
    \end{align}
    Using that $\mathbb{E}\left[\,\cdot \, \right]:=\mathbb{E}_{m\sim p}\left[\mathbb{E}_{Z_{m}\sim p_{m}^{(\lambda)}}(\,\cdot \,) \right]$, it follows
    \begin{align}
        \mathbb{E}\left[L^{(\lambda)}_N(\theta)-L^{(\lambda)}_N(\lambda)\right]&=\frac{1}{N}\sum^N_{i=1}\mathbb{E}_{m_i\sim p}\left[-2\cos(2m_i\lambda) \cos(2m_i\theta)+\cos^2(2m_i\theta)+\cos^2(2m_i\lambda) \right]\\
        &=\frac{1}{N}\sum^N_{i=1}\mathbb{E}_{m_i\sim p}\left[\mathcal{E}^{(\lambda)}_{m_i}(\theta) \right] =\mathcal{E}^{(\lambda)}(\theta),
    \end{align}
    where we have used \eqref{eq:prop_1} twice---once for $\phi=\theta$ and once for $\phi=\lambda$. Using that $\mathbb{E}\left[ \mathcal{E}^{(\lambda)}(\theta)\right]=\mathcal{E}^{(\lambda)}(\theta)$, it follows that $\mathbb{E}[D^{(\lambda)}_N(\theta)]=0$.
\end{proof}

\begin{lemma}[localization]
    \label{lemma:localization}
    Let $p$ be a window, $\lambda\in [0,\pi/2]$, $N\in\mathbb{N}_{\geq 1}$, $K\in\mathbb{N}_{\geq1}$, and $G_K$ the uniform grid of \cref{def:uniform_grid}, with spacing $\kappa$. Let $\hat{\theta}\in\arg\min_{\theta\in G_K}L^{(\lambda)}_N(\theta)$ and $A\geq 1$. If
    \begin{equation}
        \label{eq:localization}
        \max_{\theta\in G_K:|\theta-\lambda|\leq \kappa/2}\left(\mathcal{E}^{(\lambda)}(\theta)+D^{(\lambda)}_N(\theta) \right) < \min_{\theta\in G_K:|\theta-\lambda|\geq A\kappa}\left(\mathcal{E}^{(\lambda)}(\theta)+D^{(\lambda)}_N(\theta) \right),
    \end{equation}
    then $|\hat{\theta}-\lambda|< A\kappa$.
\end{lemma}
\begin{proof}
    From \cref{def:empirical_loss} we know that $L_N^{(\lambda)}(\theta)=D_N^{(\lambda)}(\theta)+L_N^{(\lambda)}(\lambda)+\mathcal{E}^{(\lambda)}(\theta)$. Hence \eqref{eq:localization} implies 
    \begin{equation}
        \max_{\theta\in G_K:|\theta-\lambda|\leq \kappa/2}L_N^{(\lambda)}(\theta) < \min_{\theta\in G_K:|\theta-\lambda|\geq A\kappa}L_N^{(\lambda)}(\theta).
    \end{equation}
    Now, let $\theta_0\in G_K$ with $|\theta_0-\lambda|\leq \kappa/2$, which exists by (R2). For any $\theta\in G_K$ with $|\theta-\lambda|\geq A\kappa$, we have
    \begin{equation}
        L_N^{(\lambda)}(\theta) \geq \min_{\theta'\in G_K:|\theta'-\lambda|\geq A\kappa}L_N^{(\lambda)}(\theta') > \max_{\theta'\in G_K:|\theta'-\lambda|\leq \kappa/2}L_N^{(\lambda)}(\theta')\ge L_N^{(\lambda)}(\theta_0),
    \end{equation}
    so no such $\theta$ attains the minimum. Hence, every $\hat{\theta}\in \arg\min_{\theta\in G_K}L^{(\lambda)}_N(\theta)$ satisfies $|\hat{\theta}-\lambda|<A\kappa$. Notably, we used the convention that $\min \emptyset =+\infty$, so that the lemma holds for all $A\geq 1$ and all $K\in \mathbb{N}\geq 1$.
\end{proof}

In the following we will derive properties of the optimal loss functions of $(b,\sigma, C,C', C'', C''')$-admissible windows. In particular, we are interested in finding lower and upper bounds on $\mathcal{E}^{(\lambda)}(\theta)$ for different parameter settings $\theta, \lambda\in [0,\pi/2]$ with respect to $T$. In the following, we will frequently use (W1), and $\mathcal{E}_0^{(\lambda)}(\theta)=0$ to write
\begin{equation}
    \mathcal{E}^{(\lambda)}(\theta)\geq \frac{b}{T}\sum^{\lfloor T \rfloor}_{m=1}\mathcal{E}_m^{(\lambda)}(\theta),
\end{equation}
as well as the identities 
\begin{equation}
    \label{eq:decomposition_of_loss}
    \mathcal{E}_m^{(\lambda)}(\theta)=4\sin^2(m(\theta+\lambda))\sin^2(m(\theta-\lambda)),
\end{equation}
and, for $x\in[-\frac{\pi}{2}, \frac{\pi}{2}]$
\begin{equation}
    \label{eq:sin_lower_bound}
    \sin^2(x)\geq \frac{4}{\pi^2}x^2.
\end{equation}

\begin{lemma}
    \label{lemma:upper_bound}
    For every $(b,\sigma, C, C', C'', C''')$-admissible window $p$, we have 
    \begin{equation}
        \mathcal{E}^{(\lambda)}(\theta)\leq C_1\min\left(1, T^2|\theta-\lambda|^2, T^4|\theta-\lambda|^2\max(\bar{\lambda}, |\theta-\lambda|)^2 \right),
    \end{equation}
    where $C_1:=4\max(1, C,9C')$ and $\bar{\lambda}:=\min(\lambda, \frac{\pi}{2}-\lambda)$.
\end{lemma}
\begin{proof}
    Define $s:=\min(\theta+\lambda, \pi-\theta-\lambda)\in [0,\pi/2]$. It is 
\begin{equation}
    \label{eq:reparametrization}
    \sin^2(ms)=\sin^2(m\pi -m(\theta+\lambda))=\sin^2(m(\theta+\lambda)),
\end{equation}
where we have used that $\sin^2$ is $\pi$-periodic and symmetric around $0$. Furthermore, for any $x,y\geq 0$ we have 
\begin{equation}
    \max(y, |x-y|)\leq x+y\leq 3\max(y, |x-y|).
\end{equation}
While the first inequality is trivial, the second follows from $x+y=(x-y)+2y\leq |x-y|+2y\leq 3\max(y, |x-y|)$. It follows
\begin{equation}
    \label{eq:min_eq_1}
    \max(\lambda, |\theta-\lambda|)\leq \theta+\lambda\leq 3\max(\lambda, |\theta-\lambda|),
\end{equation}
and
\begin{equation}
    \label{eq:min_eq_2}
    \max(\frac{\pi}{2}-\lambda, |\theta-\lambda|)=\max(\frac{\pi}{2}-\lambda, |\frac{\pi}{2}-\theta+\lambda-\frac{\pi}{2}|)\leq \pi-\theta-\lambda\leq 3\max(\frac{\pi}{2}-\lambda, |\frac{\pi}{2}-\theta+\lambda-\frac{\pi}{2}|)=3\max(\frac{\pi}{2}-\lambda, |\theta-\lambda|). 
\end{equation}
Taking the minimum of \eqref{eq:min_eq_1} and \eqref{eq:min_eq_2} and using $\min(\max(a,c), \max(b,c))=\max(\min(a,b),c)$ , it follows
\begin{equation}
    \label{eq:barlambdaidenity}
    \max(\bar{\lambda}, |\theta-\lambda|)\leq s \leq 3\max(\bar{\lambda}, |\theta-\lambda|),
\end{equation}
where $\bar{\lambda}:=\min(\lambda, \frac{\pi}{2}-\lambda)$. Moreover, we have $\sin^2(x)\leq \min(1,x^2)$ for all $x\in\mathbb{R}$. 
    Using \eqref{eq:decomposition_of_loss}, \eqref{eq:reparametrization}, and \eqref{eq:barlambdaidenity}, it follows
\begin{align}    
    \mathcal{E}_m^{(\lambda)}(\theta)&\leq 4\min\left(1, m^2s^2\right)\min\left(1, m^2(\theta-\lambda)^2\right)\\&\leq 4\min\left(1, m^2|\theta-\lambda|^2, 9m^2\max(\bar\lambda, |\theta-\lambda|)^2,  9m^4|\theta-\lambda|^2\max(\bar\lambda, |\theta-\lambda|)^2 \right)\\
    \label{eq:upper_bound_per_term_loss}
    &\leq 4\min\left(1, m^2|\theta-\lambda|^2,  9m^4|\theta-\lambda|^2\max(\bar\lambda, |\theta-\lambda|)^2 \right),
\end{align}
where we used that we always have $|\theta-\lambda|^2\leq 9\max(\bar \lambda, |\theta-\lambda|)^2$. Using (W2) and $\mathbb{E}[\min(\,\cdot\,,\,\cdot\,)]\leq \min(\mathbb{E}[\,\cdot\,], \mathbb{E}[\,\cdot\,])$, it follows
\begin{align}
    \mathcal{E}^{(\lambda)}(\theta)&\leq4\min\left(1,CT^2|\theta-\lambda|^2, 9C'T^4|\theta-\lambda|^2\max(\bar \lambda, |\theta-\lambda|)^2 \right)\\&\leq C_1\min\left(1, T^2|\theta-\lambda|^2, T^4|\theta-\lambda|^2\max(\bar \lambda, |\theta-\lambda|)^2 \right),
\end{align}
where $C_1:=4\max\left(1, C, 9C' \right)$.
\end{proof}

\begin{lemma}
    \label{lemma:lower_bound_near}
    For every $(b,\sigma, C, C', C'', C''')$-admissible window $p$ and $|\theta-\lambda|\leq \frac{\pi}{2T}$, we have 
    \begin{equation}
         \mathcal{E}^{(\lambda)}(\theta)\geq C_2T^2|\theta-\lambda|^2\min\left(1, T^2\max(\bar{\lambda}, |\theta-\lambda|)^2\right),
    \end{equation}
    where $C_2:=\frac{2b}{1215\pi^4}$ and $\bar{\lambda}:=\min(\lambda, \frac{\pi}{2}-\lambda)$.
\end{lemma}
\begin{proof}
Define $s:=\min(\theta+\lambda, \pi-\theta-\lambda)\in [0,\pi/2]$ and $\bar{\lambda}:=\min(\lambda, \frac{\pi}{2}-\lambda)$. For $|\theta-\lambda|\leq \frac{\pi}{2T}$ we can then use \eqref{eq:sin_lower_bound} and \eqref{eq:reparametrization} to obtain
    \begin{equation}
        \mathcal{E}^{(\lambda)}(\theta)\geq \frac{16b}{\pi^2T}|\theta-\lambda|^2\sum^{\lfloor T \rfloor}_{m=1}m^2\sin^2(ms).
    \end{equation}
    To proceed we will temporarily distinguish between the following two cases.
    \begin{enumerate}
        \item $T\in [1,3]$. We then have
        \begin{equation}
            \mathcal{E}^{(\lambda)}(\theta)\geq \frac{16b}{27\pi^2}T^2|\theta-\lambda|^2\sin^2(s).
        \end{equation}
        \begin{enumerate}
            \item[(i)] If $s\leq \frac{\pi}{2T}$, we use \eqref{eq:sin_lower_bound} and \eqref{eq:barlambdaidenity} to get
            \begin{equation}
                \label{eq:first_case}
                \mathcal{E}^{(\lambda)}(\theta)\geq \frac{64b}{243\pi^4}T^4|\theta-\lambda|^2s^2\geq \frac{64b}{243\pi^4}T^4|\theta-\lambda|^2\max(\bar{\lambda}, |\theta-\lambda|)^2.
            \end{equation}

            \item[(ii)] If $\frac{\pi}{2T}\leq s\leq \frac{\pi}{2}$, it is
            \begin{equation}
                \mathcal{E}^{(\lambda)}(\theta)\geq \frac{16b}{27\pi^2}T^2|\theta-\lambda|^2\sin^2(\frac{\pi}{2 T})\geq\frac{4b}{27\pi^2}T^2|\theta-\lambda|^2,
            \end{equation}
            where in the last step we have used $\sin^2(\frac{\pi}{2T})\geq \sin^2(\frac{\pi}{2\cdot 3})\geq \frac{1}{4}$.
        \end{enumerate}
        In both regimes the bound reads $\mathcal{E}^{(\lambda)}(\theta)\geq\frac{4b}{27\pi^2}T^2|\theta-\lambda|^2 c$, with $c=1$ in (ii) and $c=\frac{16}{9\pi^2}T^2\max(\bar{\lambda}, |\theta-\lambda|)^2$ in (i). Since $\min\left(1, \frac{16}{9\pi^2}T^2\max(\bar{\lambda}, |\theta-\lambda|)^2\right)$ is at most either value, we obtain
        \begin{equation}
            \label{eq:Tleq3_bound}
            \mathcal{E}^{(\lambda)}(\theta)\geq \frac{4b}{27\pi^2}T^2|\theta-\lambda|^2\min\left(1, \frac{16}{9\pi^2}T^2\max(\bar{\lambda}, |\theta-\lambda|)^2 \right)
        \end{equation}
        for all $\theta,\lambda\in[0,\frac{\pi}{2}]$ with $|\theta-\lambda|\leq \frac{\pi}{2T}$ whenever $T\in[1,3]$.

        \item $T\geq 3$. 
        \begin{enumerate}
            \item[(i)] If $s\leq \frac{3\pi}{2T}$, we use \eqref{eq:sin_lower_bound} to obtain
            \begin{align}
                \mathcal{E}^{(\lambda)}(\theta)&\geq \frac{16b}{\pi^2 T}|\theta-\lambda|^2\sum^{\lfloor T/3\rfloor}_{m=1}m^2\sin^2(ms)\\
                &\geq \frac{64b}{\pi^4 T}|\theta-\lambda|^2\max(\bar{\lambda}, |\theta-\lambda|)^2\sum^{\lfloor T/3\rfloor}_{m=1}m^4\\
                &\geq \frac{64b}{5\pi^4T}|\theta-\lambda|^2\max(\bar{\lambda}, |\theta-\lambda|)^2\lfloor T/3 \rfloor^5\\  &\geq \frac{64b}{5\cdot 6^5\pi^4}T^4|\theta-\lambda|^2\max(\bar\lambda, |\theta-\lambda|)^2\\
                \label{eq:first_bound_forTgeq3}
                &=\frac{2b}{1215\pi^4}T^4|\theta-\lambda|^2\max(\bar\lambda, |\theta-\lambda|)^2,
            \end{align}
            where we have used that
            \begin{equation}
                \sum_{m=1}^Mm^k\geq\int^{M}_0x^k\mathrm{d}x=\frac{M^{k+1}}{k+1}
            \end{equation}
            for every $M\in\mathbb{N}_{\geq 1}$, and $\lfloor T/3\rfloor^5\geq \frac{T^5}{6^5}$.

            \item[(ii)] If $\frac{3\pi}{2T}\leq s\leq \frac{\pi}{2}$, we have
            \begin{align}
                \mathcal{E}^{(\lambda)}(\theta)&\geq \frac{16b}{\pi^2T}|\theta-\lambda|^2\sum^{\lfloor T\rfloor}_{m=\lfloor T/3 \rfloor +1}m^2\sin^2(ms) \\
                &\geq \frac{8b}{9\pi^2}T|\theta-\lambda|^2\sum^{\lfloor T\rfloor}_{m=\lfloor T/3 \rfloor +1}(1-\cos(2ms)) \\
                \label{eq:last_line_reference}
                &\geq\frac{8b}{9\pi^2}T|\theta-\lambda|^2\left(\lfloor T \rfloor - \left\lfloor \frac{T}{3}\right\rfloor-\left|\sum^{\lfloor T\rfloor}_{m=\lfloor T/3 \rfloor +1}e^{i2ms}\right|\right),
            \end{align}
            where in the last step we have used that $\mathrm{Re}(z)\leq |\mathrm{Re}(z)|\leq |z|$. It is
            \begin{align}
                \sum^{\lfloor T\rfloor}_{m=\lfloor T/3 \rfloor +1}e^{i2ms}&=e^{i2(\lfloor T/3\rfloor+1)s}\sum_{m=0}^{\lfloor T \rfloor -\lfloor T/3 \rfloor-1}e^{i2ms}\\
                &=e^{i2(\lfloor T/3\rfloor+1)s}\frac{1-e^{i2(\lfloor T\rfloor -\lfloor T/3\rfloor)s}}{1-e^{i2s}},
            \end{align}
            where in the last step we used that the sum is a geometric series. To upper bound its magnitude, we can ignore the phase and notice that the numerator cannot exceed 2. For the denominator, we find
            \begin{equation}
                |1-e^{2is}|=2\sin s\geq 2\sin(\frac{3\pi}{2T})\geq \frac{6}{T}.
            \end{equation}
            It follows
            \begin{equation}
                \left|\sum^{\lfloor T\rfloor}_{m=\lfloor T/3 \rfloor +1}e^{i2ms}\right|\leq T/3.
            \end{equation}
            Inserting this bound in \eqref{eq:last_line_reference}, we obtain
            \begin{equation}
                \mathcal{E}^{(\lambda)}(\theta)\geq \frac{8b}{9\pi^2}T|\theta-\lambda|^2\left(\lfloor T \rfloor - \left\lfloor \frac{T}{3}\right\rfloor-\frac{T}{3}\right)\geq \frac{8b}{9\pi^2}T^2|\theta-\lambda|^2\left(\frac{3}{4}-\frac{2}{3} \right)\geq \frac{2b}{27\pi^2}T^2|\theta-\lambda|^2.
            \end{equation}
        \end{enumerate}
    We merge both regimes to obtain
    \begin{equation}
        \label{eq:Tgeq3_bound}
        \mathcal{E}^{(\lambda)}(\theta)\geq\frac{2b}{27\pi^2}T^2|\theta-\lambda|^2\min\left(1,\frac{1}{45\pi^2}T^2\max(\bar{\lambda}, |\theta-\lambda|)^2 \right)
    \end{equation}
    for all $\theta,\lambda\in[0,\frac{\pi}{2}]$ with $|\theta-\lambda|\leq \frac{\pi}{2T}$ whenever $T\geq 3$.
    \end{enumerate}
    Notably, \eqref{eq:Tgeq3_bound} is weaker than (and therefore implied by) \eqref{eq:Tleq3_bound}. Hence, \eqref{eq:Tgeq3_bound} holds for all $T\geq 1$. Furthermore, since $1\geq \frac{1}{45\pi^2}$, we have
    \begin{equation}
        \mathcal{E}^{(\lambda)}(\theta)\geq C_2T^2|\theta-\lambda|^2\min\left(1, T^2\max(\bar{\lambda}, |\theta-\lambda|)^2 \right),
    \end{equation}
    where $C_2:=\frac{2b}{1215\pi^4}$.
\end{proof}

\begin{lemma}
    \label{lemma:lower_bound_far}
    For every $(b,\sigma, C, C', C'', C''')$-admissible window $p$ and $|\theta-\lambda|\geq \frac{\pi}{2T}$, we have 
    \begin{equation}
        \mathcal{E}^{(\lambda)}(\theta)\geq C_3,
    \end{equation}
    where $C_3:=\frac{4}{243}b$.
\end{lemma}
\begin{proof}
    To proceed we will temporarily distinguish between the following two cases.
    \begin{enumerate}
        \item Let $T\geq 3$.
    $|\theta-\lambda|\geq \frac{\pi}{2T}$ implies $\theta+\lambda \in [\frac{\pi}{2T}, \pi-\frac{\pi}{2T}]$. We can expand
    \begin{equation}
        \mathcal{E}^{(\lambda)}_m(\theta)=1+\frac{1}{2}\left(\cos(4m\theta)+\cos(4m\lambda)\right)-\cos(2m(\theta+\lambda))-\cos(2m(\theta-\lambda))
    \end{equation}
    and use
    \begin{equation}
        \sum_{m=1}^M\cos(mx)=\frac{\sin(x(M+\frac{1}{2}))}{2\sin(x/2)}-\frac{1}{2}
    \end{equation}
    to obtain
    \begin{equation}
        \mathcal{E}^{(\lambda)}(\theta)\geq \frac{b}{2T}\left(2\lfloor T \rfloor+1-D_{\lfloor T \rfloor}(2(\theta+\lambda))-D_{\lfloor T \rfloor}(2(\theta-\lambda))+\frac{1}{2}D_{\lfloor T \rfloor}(4\theta)+\frac{1}{2}D_{\lfloor T \rfloor}(4\lambda) \right),
    \end{equation}
    where 
    \begin{equation}
        D_M(x):=\frac{\sin(x(M+\frac{1}{2}))}{\sin(x/2)}
    \end{equation}
    is the Dirichlet kernel. We need a lower bound on $D_M(x)$ for $x\in [0,2\pi]$ and an upper bound on $D_M(x)$ for $x\in[\frac{\pi}{T}, 2\pi-\frac{\pi}{T}]$. We start by finding the lower bound. Let $L:=M+\frac{1}{2}$ and consider the following cases:
    \begin{enumerate}
        \item $x\in [0,\frac{\pi}{L}]$. Here we have $D_M(x)\geq 0$
        \item $x\in [\frac{\pi}{L}, \pi]$. Here we have $0\leq x/2\leq \pi/2$. It follows
        \begin{equation}
            \frac{1}{\sin(x/2)}\leq \frac{\pi}{x}. 
        \end{equation}
        Hence, we have
        \begin{equation}
            D_M(x)\geq \min\left(0, \pi \frac{\sin(xL)}{x} \right).
        \end{equation}
        With 
        \begin{equation}
            \pi \frac{\sin(xL)}{x}=L\pi\frac{\sin(xL)}{xL}\geq L\pi \inf_{\pi\leq y \leq L\pi}\frac{\sin y}{y}\geq L\pi \inf\frac{\sin y}{y}> -0.7L, 
        \end{equation}
        it follows $D_M(x)\geq -0.7L$.
        \item $x\in [\pi, 2\pi]$. $\sin(x)$ is symmetric around $x=\pi/2+k\pi$ for $k\in\mathbb{Z}$. Hence, both $\sin(x/2)$ and $\sin(Lx)=\sin((M+1/2)x)$ are symmetric around $\pi$. Therefore, also $D_M(x)$ is symmetric around $\pi$ and we obtain the same bounds as in the other two cases.
    \end{enumerate}
    Consequently, we have $D_M(x)\geq -0.7L$ for all $x\in[0,2\pi]$ (and also all $x\in\mathbb{R}$). We now derive the upper bound. Because of the symmetry of $D_M(x)$ around $\pi$, it is sufficient to find an upper bound for $x\in [\frac{\pi}{T}, \pi]$. In this region we can write
    \begin{equation}
        D_M(x)\leq \max\left(0, \pi\frac{\sin(xL)}{x} \right).
    \end{equation}
    With
    \begin{equation}
        \pi\frac{\sin(xL)}{x}\leq L\pi\sup_{\frac{\pi L}{T}\leq y}\frac{\sin y}{y} .
    \end{equation}
    For $L=\lfloor T \rfloor +1/2$ and $T\geq 3$, we have $\frac{\pi L}{T}=\pi \frac{\lfloor T\rfloor+\frac{1}{2}}{T}\geq \frac{7}{8}\pi$ and 
    \begin{equation}
        \pi\sup_{\frac{7\pi}{8}\leq y}\frac{\sin y}{y}<0.44.
    \end{equation}
    Hence, $D_M(x)\leq 0.44L=0.44(\frac{1}{2}+\lfloor T \rfloor)$. Putting everything together, for $T\geq 3$, it follows
    \begin{align}
        \mathcal{E}^{(\lambda)}(\theta)&\geq \frac{b}{2T}(1-0.44-0.35)\left(2\lfloor T \rfloor+1\right)\\
        &=0.21b\frac{\lfloor T\rfloor +\frac{1}{2}}{T}> 0.18b.
    \end{align}
    \item Let $T\in [1,3]$. As before, we can use that $|\theta-\lambda|\geq \frac{\pi}{2T}$ implies $\theta+\lambda \in [\frac{\pi}{2T}, \pi-\frac{\pi}{2T}]$ to find
    \begin{align}
        \mathcal{E}^{(\lambda)}(\theta)&\geq \frac{4b}{T}\sum^{\lfloor T \rfloor}_{m=1}\sin^2(m(\theta+\lambda))\sin^2(m(\theta-\lambda))\\
        &\geq \frac{4b}{T}\sin^2(\theta+\lambda)\sin^2(\theta-\lambda)\\
        &\geq \frac{4b}{T^5}\geq \frac{4b}{3^5}=\frac{4}{243}b.
    \end{align}
    \end{enumerate}
    Consequently, for $|\theta-\lambda|\geq \frac{\pi}{2T}$, we have $\mathcal{E}^{(\lambda)}(\theta)\geq \frac{4}{243}b$ for all $T\geq 1$.
\end{proof}

\begin{corollary}
    \label{cor:lower_bound}
    For every $(b,\sigma, C,C', C'', C''')$-admissible window $p$ we have
    \begin{equation}
        \mathcal{E}^{(\lambda)}(\theta)\geq C_2\min\left(1, T^2|\theta-\lambda|^2, T^4|\theta-\lambda|^2\max(\bar \lambda, |\theta-\lambda|)^2 \right),      
    \end{equation}
    where $C_2:=\frac{2b}{1215\pi^4}$ and $\bar\lambda:=\min(\lambda, \frac{\pi}{2}-\lambda)$.
\end{corollary}
\begin{proof}
    We can combine \cref{lemma:lower_bound_near} and \cref{lemma:lower_bound_far} to obtain 
    \begin{align}
        \mathcal{E}^{(\lambda)}(\theta)&\geq \min\left(C_3,C_2T^2|\theta-\lambda|^2\min(1, T^2\max(\bar\lambda, |\theta-\lambda|)^2)  \right)\\
        &\geq C_2\min\left(1, T^2|\theta-\lambda|^2, T^4|\theta-\lambda|^2\max(\bar\lambda, |\theta-\lambda|)^2 \right)
    \end{align}
    for all $\theta, \lambda\in [0,\frac{\pi}{2}]$, where we have used that $C_2<C_3$.
\end{proof}
\begin{corollary}
    \label{cor:envelope}
    For every $(b, \sigma,C, C', C'', C''')$-admissible window $p$ we have
    \begin{equation}
        C_2\Psi(|\theta-\lambda|)^2\leq \mathcal{E}^{(\lambda)}(\theta)\leq C_1\Psi(|\theta-\lambda|)^2,
    \end{equation}
    where $\Psi(\Delta):=\min\left(1, T\Delta, T^2\Delta\max(\bar \lambda, \Delta) \right)$ and $\bar\lambda:=\min(\lambda, \frac{\pi}{2}-\lambda)$.
\end{corollary}
\begin{proof}
    Immediate consequence of \cref{lemma:upper_bound} and \cref{cor:lower_bound}.
\end{proof}

\begin{lemma}[concentration of empirical fluctuation]
    \label{lemma:concentration}
    Let $p$ be a $(b,\sigma,C, C', C'', C''')$-admissible window, $\lambda\in [0,\pi/2]$, $N\in\mathbb{N}_{\geq 1}$, $\delta\in(0,1)$, $K\in\mathbb{N}_{\geq 1}$, and $G_K$ the uniform grid of \cref{def:uniform_grid}. Then, with probability at least $1-\delta$, we have
    \begin{equation}
        |D_N^{(\lambda)}(\theta)|\leq C_{8}\max\left(r\Psi(|\theta-\lambda|), \sqrt{r}\Omega(|\theta-\lambda|) \right)
    \end{equation}
    for all $\theta\in G_K$, where $r=\frac{\log(2K/\delta)}{N}$, $C_8:=\sqrt{32}\max\left(24\sigma^2, 4C, 36C',12\sqrt{2C''}, 18\sqrt{2C'''}\right)$, and 
    \begin{equation}
        \Psi(\Delta):=\min\left(1, T\Delta, T^2\Delta\max(\bar\lambda, \Delta) \right),\qquad\Omega(\Delta):=\min\left(1, \min\left( 1,T^2\max(\bar\lambda, \Delta)^2\right)\max\left[T\min(\bar\lambda, \Delta), T^2\Delta^2\right] \right),
    \end{equation}
    where $\bar\lambda:=\min(\lambda, \frac{\pi}{2}-\lambda)$
\end{lemma}

\begin{proof}
    For $i\in\{1,...,N\}$, define $X_i(\theta):=(Z_{i}-\cos(2m_i\theta))^2-(Z_{i}-\cos(2m_i\lambda))^2-\mathcal{E}^{(\lambda)}(\theta)$, such that $D_N^{(\lambda)}(\theta)=\frac{1}{N}\sum_{i=1}^NX_i(\theta)$. For now we drop the index $i$ and treat $X(\theta)$ as a single random variable. Using $Z_{m}^2=1$, we can write
    \begin{align}
        X(\theta)&=2Z_{m}(\cos(2m\lambda)-\cos(2m\theta))+\cos^2(2m\theta)-\cos^2(2m\lambda)-\mathcal{E}^{(\lambda)}(\theta)\\
        &=2(\cos(2m\lambda)-Z_{m})(\cos(2m\theta)-\cos(2m\lambda))-\mathcal{E}^{(\lambda)}(\theta)+\mathcal{E}_{m}^{(\lambda)}(\theta),
    \end{align}
    to see that $\mathbb{E}[X(\theta)]=0$. Using the law of total variance, it follows
    \begin{align}
        \label{eq:var}
        \mathrm{Var}\left[X(\theta) \right]&=\mathbb{E}_{m\sim p}\left[\mathrm{Var}\left[X(\theta)\mid m \right] \right]+\mathrm{Var}_{m\sim p}\left[\mathbb{E}\left[X(\theta)\mid m \right] \right]\\
        &=\mathbb{E}_{m\sim p}\left[\mathrm{Var}_{Z_{m}\sim p_{m}^{\lambda}}\left[X(\theta) \right] \right]+\mathrm{Var}_{m\sim p}\left[\mathbb{E}_{Z_{m}\sim p_{m}^{\lambda}}\left[X(\theta)\right] \right],
    \end{align}
    where, using (R1), $\mathbb{E}_{Z_{m}\sim p_{m}^{\lambda}}\left[X(\theta)\right]=-\mathcal{E}(\theta)+\mathcal{E}_m(\theta)$ and $\mathrm{Var}_{Z_{m}\sim p_{m}^{\lambda}}\left[X(\theta) \right]=4\mathcal{E}^{(\lambda)}_m(\theta)\mathrm{Var}_{Z_{m}\sim p_{m}^{\lambda}}\left[Z_{m} \right]=4\mathcal{E}^{(\lambda)}_m(\theta)\sin^2(2m\lambda)$. The first term on the RHS of \cref{eq:var} corresponds to the measurement noise of the binary variable $Z_m$, while the second term captures the additional variance induced by randomly sampling $m$. As before (see \eqref{eq:upper_bound_per_term_loss}) we obtain
    \begin{equation}
        \mathcal{E}^{(\lambda)}_m(\theta)\leq 4\min\left(1, m^2|\theta-\lambda|^2,  9m^4|\theta-\lambda|^2v^2 \right),
    \end{equation}
    where we have defined $v:=\max(\bar \lambda, |\theta-\lambda|)$ and $\sin^2(2m\lambda)=\sin^2(2m\bar\lambda)\leq \min(1, 4m^2\bar{\lambda}^2)$. It follows
    \begin{equation}
        \mathrm{Var}_{Z_{m}\sim p_{m}^{\lambda}}\left[X(\theta)\right]\leq 16\min\left(1, m^2|\theta-\lambda|^2, 9m^4|\theta-\lambda|^2v^2, 4m^2\bar\lambda^2, 4m^4|\theta-\lambda|^2\bar\lambda^2, 36m^6|\theta-\lambda|^2v^2\bar\lambda^2 \right).
    \end{equation}
    Notably, we always have $4m^4\bar\lambda^2\leq 9m^4v^2$, which allows us to drop the $9m^4|\theta-\lambda|^2v^2$ term. Using (W2), it follows
    \begin{align}
        \mathbb{E}_{m\sim p}\left[\mathrm{Var}_{Z_{m}\sim p_{m}^{\lambda}}\left[X(\theta) \right] \right]&\leq 16\min\left(1, CT^2\min(|\theta-\lambda|, 2\bar\lambda)^2, 4C'T^4|\theta-\lambda|^2\bar\lambda^2, 36C''T^6|\theta-\lambda|^2v^2\bar\lambda^2\right)\\
        &\leq C_4\min\left(1, T^2\min(|\theta-\lambda|, \bar\lambda)^2, T^4|\theta-\lambda|^2\bar\lambda^2, T^6|\theta-\lambda|^2v^2\bar\lambda^2 \right),
    \end{align}
    where $C_4:=16\max(1, 4C, 4C', 36C'')$. Notably, we can also drop the $T^4|\theta-\lambda|^2\bar\lambda^2$ term. To see this notice that $\min(a,b)\max(a,b)=ab$ for all $a,b\in \mathbb{R}$. Define $u:=\min(|\theta-\lambda|,\bar\lambda)$. Then $|\theta-\lambda|^2\bar\lambda^2=v^2u^2$. Therefore, we have
    \begin{align}
        \min\left(T^2u^2, T^4|\theta-\lambda|^2\bar{\lambda}^2, T^6|\theta-\lambda|^2v^2\bar\lambda^2 \right)=&\min\left( T^2u^2, T^4u^2v^2, T^6u^2v^4\right)\\
        =&T^2u^2\min\left(1, T^2v^2, T^4v^4 \right).
    \end{align}
    If $Tv\geq 1$, the constant term is the smallest. If $Tv<1$, the quartic term is the smallest. Hence, in neither case we need the second term so that we can drop it. Furthermore, (W2) gives us
    \begin{align}
        \mathrm{Var}_{m\sim p}\left[\mathbb{E}_{Z_{m}\sim p_{m}^{\lambda}}\left[X(\theta)\right] \right]&\leq \mathbb{E}_{m\sim p}[(\mathcal{E}^{(\lambda)}_m)^2]\\
        &\leq 16\min\left(1, C'T^4|\theta-\lambda|^4, 81C'''T^8|\theta-\lambda|^4v^4 \right)\\
        &\leq C_5\min\left(1, T^4|\theta-\lambda|^4, T^8|\theta-\lambda|^4v^4 \right),
    \end{align}
    where $C_5:=16\max(1, C', 81C''')$. For notational convenience set $\Delta:=|\theta-\lambda|$ and $u:=\min(\Delta, \bar\lambda)$. As before, we will use that $uv=\Delta\bar\lambda$.
    With $C_6:=2\max(C_4,C_5)=32\max(1,4C, 4C', 36C'', 81C''')$, it follows
    \begin{align}
        \mathrm{Var}\left[X(\theta) \right]&\leq 2\max\left(\mathbb{E}_{m\sim p}\left[\mathrm{Var}_{Z_{m}\sim p_{m}^{\lambda}}\left[X(\theta) \right] \right], \mathrm{Var}_{m\sim p}\left[\mathbb{E}_{Z_{m}\sim p_{m}^{\lambda}}\left[X(\theta)\right] \right] \right)\\
        &\leq C_6\max\left[\min\left(1, T^2u^2, T^6v^4u^2 \right),  \min\left(1, T^4\Delta^4, T^8\Delta^4v^4 \right)\right]\\
        &= C_6\min\left(1,\max \left[T^2u^2\min\left(1,T^4v^4 \right),T^4\Delta^4\min\left(1, T^4v^4 \right) \right]\right)\\
        &=C_6\min\left(1, \min\left( 1,T^4v^4\right)\max\left[T^2u^2, T^4\Delta^4\right] \right)=:V.
    \end{align}
    Moreover, we find
    \begin{align}
        |X(\theta)|&\leq \left|\left(-2Z_m+(\cos(2m\lambda)+\cos(2m\theta) )\right)\left(\cos(2m\theta)-\cos(2m\lambda) \right)\right|+\mathcal{E}^{(\lambda)}(\theta)\\
        &\leq 8\left|\sin(m(\theta-\lambda))\sin(m(\theta+\lambda)) \right|+\mathcal{E}^{(\lambda)}(\theta)\\
        &\leq 8\min\left(1,m|\theta-\lambda|, 3m^2|\theta-\lambda|v \right)+C_1\min\left(1, T^2|\theta-\lambda|^2, T^4|\theta-\lambda|^2v^2\right)\\
        &\leq C_7\min\left(1,T|\theta-\lambda|, T^2|\theta-\lambda|v \right)=:B,
    \end{align}
    where we have used \eqref{eq:reparametrization}, \eqref{eq:barlambdaidenity}, and $C_7:=2\max(C_1, 24\sigma^2)$. For any fixed $\theta\in G_K$, Bernstein's inequality yields, for every $\eta>0$,
    \begin{equation}
        \mathrm{Pr}\left(\left|D^{(\lambda)}_N(\theta)\right|\geq \eta \right)\leq 2\exp\left(-\frac{N\eta^2}{2\left(V+\frac{B\eta}{3}\right)}\right),
    \end{equation}
    where $B$ and $V$ depend implicitly on $\theta$. To obtain a bound holding simultaneously for all $K$ grid points, for each $\theta\in G_K$ we choose a threshold $\eta=\eta(\theta)$ such that the right-hand side at most $\delta/K$. Equivalently, it suffices that
    \begin{align}
         2K\exp\left(-\frac{N\eta^2}{2\left(V+\frac{B\eta}{3}\right)}\right)&\leq \delta 
    \end{align}
    Defining $L:=\log(2K/\delta)$, this is equivalent to 
    \begin{equation}
         \eta^2-\frac{2BL}{3N}\eta-\frac{2VL}{N}\geq 0,
    \end{equation}
    and hence implied by 
    \begin{equation}
        \eta \geq \frac{\frac{2BL}{3N}+\sqrt{(\frac{2BL}{3N})^2+4\frac{2VL}{N}}}{2}=\frac{BL}{3N}+\sqrt{(\frac{BL}{3N})^2+\frac{2VL}{N}}:=\eta^*.
    \end{equation}
    Using $\sqrt{x}+\sqrt{y}\geq \sqrt{x+y}$, it follows that 
    \begin{equation}
        \frac{2BL}{3N}+\sqrt{\frac{2VL}{N}}\geq \eta^*.
    \end{equation}
    Therefore, setting $r=L/N$, each grid point satisfies 
    \begin{equation}
        \mathrm{Pr}\left(\left|D^{(\lambda)}_N(\theta)\right|\geq \frac{2}{3}Br+\sqrt{2Vr}\right)\leq \delta/K.
    \end{equation}
    A union bound over all $\theta\in G_K$ then gives, with probability at least $1-\delta$, simultaneously for every $\theta\in G_K$,
    \begin{align}
        |D^{(\lambda)}_N(\theta)|&\leq \frac{2}{3}Br+\sqrt{2Vr}\leq \sqrt{8}\max\left(Br, \sqrt{Vr} \right)=C_8\max(r\Psi(\Delta), \sqrt{r}\Omega(\Delta)),
    \end{align}
    where 
    \begin{align}
    C_8 &:= \sqrt{8}\max\!\left(\sqrt{C_6}, C_7\right) \\
    &= \sqrt{8}\max\left(4\sqrt2\max(1, 2\sqrt{C}, 2\sqrt{C'}, 6\sqrt{C''}, 9\sqrt{C'''}),
        2\max(4, 4C, 36C', 24\sigma^2)\right) \\
    &= \sqrt{32}\max\left(24\sigma^2, \sqrt{32C}, 4C, \sqrt{32C'}, 36C', 12\sqrt{2C''}, 18\sqrt{2C'''}\right)\\
    &= \sqrt{32}\max\left(24\sigma^2, 4C, 36C',12\sqrt{2C''}, 18\sqrt{2C'''}\right),
    \end{align}
    where we have used $\sigma^2\geq 1$ to absorb the constant entries, together with $\max(24\sigma^2, 4C)\geq \sqrt{32C}$ and $\max(24\sigma^2, 36C')\geq \sqrt{32C'}$. Furthermore, we defined
    \begin{equation}
        \Psi(\Delta):=\min\left(1, T\Delta, T^2\Delta v \right),\qquad\Omega(\Delta):=\min\left(1, \min\left( 1,T^2v^2\right)\max\left[Tu, T^2\Delta^2\right] \right).
    \end{equation}
\end{proof}
\begin{remark}
    \label{remark:variance}
    Define $Y_i(\theta):=X_i(\theta)+\mathcal{E}^{(\lambda)}(\theta)=(Z_i-\cos(2m_i\theta))^2-(Z_i-\cos(2m_i\lambda))^2$ such that $L^{(\lambda)}(\theta)-L^{(\lambda)}(\lambda)=\frac{1}{N}\sum^N_{i=1}Y_i$. Since $Y_i$ and $X_i$ are related by a deterministic additive term, i.e. the optimal loss $\mathcal{E}^{(\lambda)}(\theta)$, both random variables have the same variance and range. For $\Delta\leq 1/T\Leftrightarrow \Delta T\leq 1$ we have 
    \begin{align}
        \Omega(\Delta)&=\min\left( 1,T^2\max(\bar\lambda, \Delta)^2\right)\max\left[T\min(\bar\lambda, \Delta), T^2\Delta^2\right]\leq \min\left(T\Delta,T^3\Delta\max(\bar\lambda, \Delta)^2\right)=\frac{\Psi^2(\Delta)}{T\Delta},
    \end{align}
    implying
    \begin{equation}
        \mathrm{Var}[Y_i]\leq C_6\Omega^2(\Delta)\leq C_6\frac{\Psi^4(\Delta)}{T^2\Delta^2}.
    \end{equation}
    Furthermore, we have
    \begin{equation}
        \max Y_i(\theta)-\min Y_i(\theta)\leq C_7\Psi(\Delta).
    \end{equation}
\end{remark}

\begin{lemma}
    \label{lemma:main}
    Let $M,N\in\mathbb{N}_{\geq 1}$, let $p$ be a $(b,\sigma,C,C',C'',C''')$-admissible window on $\mathcal{W}_M$ with $T=\max(1,M/\sigma)$, and let $\lambda\in[0,\pi/2]$, $\delta\in(0,1)$, and $\epsilon\in(0,1/T]$. Set $A=\frac{3C_8}{8C_2}$ and $C_9=\frac{(1+A)C_8}{C_2A^2-C_1}$, where $C_1$, $C_2$, $C_8$ are defined as in \cref{lemma:upper_bound}, \cref{lemma:lower_bound_near} and \cref{lemma:concentration}, and let $G_K$ be the uniform grid from \cref{def:uniform_grid} with $K=\lceil\frac{A\pi}{2\epsilon}\rceil$. Then, if
    \begin{equation}
    \label{eq:lemma_cond}
    T\sqrt{N}\geq \frac{2AC_9}{\epsilon}\sqrt{\log\left(\frac{2A\pi}{\epsilon\delta}\right)},
    \end{equation}
    any minimizer $\hat{\theta}\in\arg\min_{\theta\in G_K}L^{(\lambda)}_N(\theta)$ satisfies $|\hat{\theta}-\lambda|\leq\epsilon$ with probability at least $1-\delta$.
\end{lemma}

\begin{proof}
Define
\begin{equation}
    U:=\max_{\theta\in G_K:|\theta-\lambda|\leq \kappa/2}\left(\mathcal{E}^{(\lambda)}(\theta)+D^{(\lambda)}_N(\theta) \right)
\end{equation}
and
\begin{align}
    L:&=\min_{\theta\in G_K:|\theta-\lambda|\geq A\kappa}\left(\mathcal{E}^{(\lambda)}(\theta)+D^{(\lambda)}_N(\theta) \right)\\
    &=\min\left[\min_{\theta\in G_K:A\kappa\leq |\theta-\lambda|\leq 1/T}\left(\mathcal{E}^{(\lambda)}(\theta)+D^{(\lambda)}_N(\theta) \right), \min_{\theta\in G_K:|\theta-\lambda|\geq 1/T}\left(\mathcal{E}^{(\lambda)}(\theta)+D^{(\lambda)}_N(\theta) \right)\right]=:\min\left[L_\mathrm{near}, L_\mathrm{far}\right].
\end{align}
To satisfy \eqref{eq:localization} of \cref{lemma:localization}, we require $U< L_\mathrm{near}$ and $U< L_\mathrm{far}$. Let $\Psi$ and $\Omega$ be defined as in \cref{lemma:concentration}, and assume $0<A\kappa\leq \frac{1}{T}\implies 0<\kappa\leq \frac{1}{T}$ and distinguish the following two cases:
\begin{enumerate}
    \item Let $\bar\lambda\leq \frac{1}{T}$. It follows 
    \begin{equation}
        \Psi(\Delta)=T^2\Delta v_\Delta,\qquad\Omega(\Delta)=T^3v_\Delta^2\max(u_\Delta, T\Delta^2)\leq T^3\Delta v^2_\Delta,
    \end{equation}
    for all $\Delta\leq 1/T$, where $v_\Delta:=\max(\bar\lambda, \Delta)$ and $u_\Delta:=\min(\bar\lambda, \Delta)$. Furthermore, assume that $\max(r, \sqrt{r}Tv_\Delta)=\sqrt{r}Tv_\Delta$ for all $\kappa/2\leq \Delta \leq 1/T$. This is implied by $\sqrt{r}\leq T\kappa/2$. Using \cref{lemma:upper_bound} and \cref{lemma:concentration}, it follows
    \begin{equation}
        U\leq C_1T^4\frac{\kappa^2}{4}v_{\kappa/2}^2+C_8\sqrt{r}T^3\frac{\kappa}{2} v_{\kappa/2}^2<  C_1T^4\kappa^2v_\kappa^2+C_8\sqrt{r}T^3\kappa v_\kappa^2,
    \end{equation}
    where we have used that $\Psi(\Delta)$ and $\Omega(\Delta)$ are non-decreasing, so $\Psi(\Delta)\leq \Psi(\kappa/2)$ and $\Omega(\Delta)\leq \Omega(\kappa/2)$ for all $\Delta\leq \kappa/2$. Furthermore, using \cref{cor:lower_bound} and \cref{lemma:concentration}, we have
    \begin{equation}
        L_\mathrm{near}\geq \min_{\theta\in G_K:A\kappa\leq \Delta\leq 1/T}l(\Delta),\qquad l(\Delta):=C_2T^4\Delta^2v_\Delta^2-C_8\sqrt{r}T^3\Delta v^2_\Delta.
    \end{equation}
    We want $l(\Delta)$ to be non-decreasing on $[A\kappa, 1/T]$. The first term is increasing in $\Delta$, whereas the second term is decreasing in $\Delta$. Hence, for $\Delta\geq\bar\lambda$, we require
    \begin{equation}
        \frac{\partial l(\Delta)}{\partial \Delta}\bigg|_{\Delta\geq \lambda}=4C_2T^4\Delta^3-3C_8\sqrt{r}T^3\Delta^2\geq 0\Longleftrightarrow \Delta\geq \frac{3C_8}{4C_2T}\sqrt{r},
    \end{equation}
    whereas for $\Delta \leq \bar\lambda$, we require
    \begin{equation}
        \frac{\partial l(\Delta)}{\partial \Delta}\bigg|_{\Delta\leq \lambda}=2C_2T^4\Delta\bar\lambda^2-C_8\sqrt{r}T^3\bar\lambda^2\geq 0\Longleftrightarrow \Delta\geq \frac{C_8}{2C_2T}\sqrt{r}.
    \end{equation}
    Since $\sqrt{r}\leq T\kappa/2$, a sufficient condition for both regimes is $\Delta \geq\frac{3C_8}{8C_2}\kappa$. Therefore, we set $A=\frac{3C_8}{8C_2}$. Since $b \leq 1$ and $\sigma \geq 1$, we have $C_2 = \frac{2b}{1215\pi^4} < 1.7\cdot 10^{-5}$ and $C_8 \geq 24\sqrt{32}\,\sigma^2 > 135$, so that $A > 3\cdot 10^{6} \geq 1$. Since we require $A\kappa\leq 1/T$, we must set $\kappa\leq \frac{1}{AT}$ and then require $\sqrt{r}\leq \frac{1}{2A}$. For this choice of $A$, we have
    \begin{equation}
        \min_{\theta\in G_K:A\kappa\leq \Delta\leq 1/T}l(\Delta)\geq l(A\kappa).
    \end{equation}
    Therefore, $U< L_\mathrm{near}$ is implied by
    \begin{align}
        C_1T^4\kappa^2v^2_{\kappa}+C_8\sqrt{r}T^3\kappa v^2_\kappa\leq C_2T^4A^2\kappa^2v_{A\kappa}^2-C_8\sqrt{r}T^3A\kappa v_{A\kappa}^2.
    \end{align}
    Using $v_\kappa\leq v_{A\kappa}$, a sufficient condition is
        \begin{align}
            C_1T^4\kappa^2v^2_{A\kappa}+C_8\sqrt{r}T^3\kappa v^2_{A\kappa}&\leq C_2T^4A^2\kappa^2v_{A\kappa}^2-C_8\sqrt{r}T^3A\kappa v_{A\kappa}^2\\
            (1+A)C_8\sqrt{r}T^3\kappa v^2_{A\kappa}&\leq (C_2A^2-C_1)T^4\kappa^2v_{A\kappa}^2\\
            \frac{T}{\sqrt{r}}&\geq \frac{(1+A)C_8}{C_2A^2-C_1}\frac{1}{\kappa}=:C_9\frac{1}{\kappa}.
        \end{align}
        Notably, we have
        \begin{equation}
            C_2A^2-C_1=\frac{9C_8^2}{64C_2}-C_1\geq\left( \frac{9}{64}\frac{1215\pi^4}{2b}-1\right)C_1>0,
        \end{equation}
        where we have used that $C_8^2\geq C_1$, which is true, because $C_8\geq \max(1, C_1)$, and that $b\leq 1$. Therefore, choosing 
    \begin{equation}
        \frac{T}{\sqrt{r}}\geq C_9\frac{1}{\kappa}
    \end{equation}
    is sufficient to satisfy $U< L_\mathrm{near}$. Notably, $C_9\geq \frac{C_8}{C_2A}\geq \frac{8}{3}>2$. Therefore, this choice also implies the assumption $T/\sqrt{r}\geq \frac{2}{\kappa}$. Additionally, we require $U< L_\mathrm{far}$. For $\Delta\geq 1/T$, we have
    \begin{equation}
        \Psi(\Delta)=1,\qquad \Omega(\Delta) =1.
    \end{equation}
    Hence, using \cref{cor:lower_bound} and \cref{lemma:concentration}, we have 
    \begin{equation}
        L_\mathrm{far}\geq C_2-C_8\sqrt{r},
    \end{equation}
    where we have used that $\sqrt{r}\leq T\kappa/2\leq 1$. Therefore, $U< L_\mathrm{far}$ is implied by
    \begin{equation}
        C_1T^4\kappa^2 v^2_\kappa +C_8\sqrt{r}T^3\kappa v_\kappa^2=T^3\kappa v_\kappa^2(T\kappa C_1+C_8\sqrt{r})\leq C_2-C_8\sqrt{r}.
    \end{equation}
    Since $Tv_\kappa \leq 1$ and $T\kappa \leq \frac{1}{A}$, a sufficient condition is
    \begin{equation}
        \frac{C_1}{A^2}+\frac{C_8\sqrt{r}}{A}\leq C_2-C_8\sqrt{r}\Longleftrightarrow \frac{1}{\sqrt{r}}\geq AC_9.
    \end{equation}
    Notably, since $A\kappa\leq 1/T\Leftrightarrow A\leq \frac{1}{T\kappa}$, this condition is satisfied whenever $T/\sqrt{r}\geq C_9/\kappa$. Therefore, $U< L_\mathrm{far}$ is implied by $U< L_\mathrm{near}$. Hence, choosing $T/\sqrt{r}\geq C_9/\kappa$ is sufficient to satisfy \eqref{eq:localization}.

    \item Let $\bar\lambda\geq \frac{1}{T}$. It follows $v=\bar\lambda$, $u=\Delta$ and thus
    \begin{equation}
        \Psi(\Delta)=T\Delta,\qquad \Omega(\Delta)=T\Delta.
    \end{equation}
    Furthermore, assume that $\sqrt{r}\leq T\kappa/2 $, which implies $\sqrt{r}\geq r$. Using \cref{lemma:upper_bound} and \cref{lemma:concentration}, it follows
    \begin{equation}
        U< C_1T^2\kappa^2 + C_8\sqrt{r}T\kappa,
    \end{equation}
    and, using \cref{cor:lower_bound} and \cref{lemma:concentration}, 
    \begin{equation}
        L_\mathrm{near}\geq \min_{\theta\in G_K:A\kappa\leq \Delta\leq 1/T}l(\Delta),\qquad l(\Delta):=C_2T^2\Delta^2-C_8\sqrt{r}T\Delta.
    \end{equation}
    We want $l(\Delta)$ to be non-decreasing on $[A\kappa, 1/T]$. Therefore, we require
    \begin{equation}
        \frac{\partial l(\Delta)}{\partial \Delta}=2C_2T^2\Delta-C_8\sqrt{r}T\geq 0\Longleftrightarrow \Delta\geq \frac{C_8}{2C_2T}\sqrt{r}.
    \end{equation}
    Since $\sqrt{r}\leq T\kappa/2 $, $\Delta\geq \frac{3C_8}{8C_2}\kappa$ is a sufficient condition. Therefore, we can again set $A=\frac{3C_8}{8C_2}$, and---since we require $A\kappa \leq \frac{1}{T}$---we must set $\kappa\leq\frac{1}{AT}$ and then require $\sqrt{r}\leq \frac{1}{2A}$. We then have 
    \begin{equation}
        \min_{\theta\in G_K:A\kappa\leq \Delta\leq 1/T}l(\Delta)\geq l(A\kappa).
    \end{equation}
    Therefore, $U< L_\mathrm{near}$ is implied by
    \begin{align}
        C_1T^2\kappa^2+C_8\sqrt{r}T\kappa&\leq C_2T^2A^2\kappa^2-C_8\sqrt{r}TA\kappa\\
        (1+A)C_8\sqrt{r}T\kappa &\leq (C_2A^2-C_1)T^2\kappa^2\\
        \frac{T}{\sqrt{r}}&\geq C_9\frac{1}{\kappa}.
    \end{align}
    Therefore, also in this regime, choosing $\frac{T}{\sqrt{r}}\geq C_{9}\frac{1}{\kappa}$ is sufficient to satisfy $U< L_\mathrm{near}$ and implies $\sqrt{r}\leq T\kappa/2$. Additionally, we require $U< L_\mathrm{far}$. As before, also in this regime, we have $L_\mathrm{far}\geq C_2-C_8\sqrt{r}$. Therefore, $U< L_\mathrm{far}$ is implied by
    \begin{equation}
        C_1T^2\kappa^2+C_8\sqrt{r}T\kappa =T\kappa(T\kappa C_1+C_8\sqrt{r})\leq C_2-C_8\sqrt{r}.
    \end{equation} 
    Since $T\kappa \leq \frac{1}{A}$, a sufficient condition is
    \begin{equation}
        \frac{C_1}{A^2}+\frac{C_8\sqrt{r}}{A}\leq C_2-C_8\sqrt{r}\Longleftrightarrow \frac{1}{\sqrt{r}}\geq AC_9,
    \end{equation}
    which again is implied by $\frac{T}{\sqrt{r}}=C_{9}\frac{1}{\kappa}$.
    Therefore, choosing $T/\sqrt{r}\geq C_9/\kappa$ is sufficient to satisfy \eqref{eq:localization}. 
\end{enumerate}
Consequently, choosing $T/\sqrt{r}=C_9/\kappa$ is sufficient to satisfy \eqref{eq:localization} for all $\bar\lambda$ and consequently also for all $\lambda$. Therefore, for any $\epsilon\in (0,1/T]$ and any $\delta\in (0,1)$, choosing $N\in \mathbb{N}_{\geq 1}$ such that 
\begin{equation}
    T\sqrt{N}\geq \frac{2AC_9}{\epsilon}\sqrt{\log\left(\frac{2A\pi}{\epsilon \delta} \right)} \overset{*}{\implies} T\sqrt{N}\geq \frac{2KC_9}{\pi}\sqrt{\log\left(\frac{2K}{\delta} \right)}\Longleftrightarrow \frac{T}{\sqrt{r}}\geq \frac{C_9}{\kappa}
\end{equation}
is sufficient to ensure that any minimizer $\hat{\theta}\in\arg\min_{\theta\in G_K}L^{(\lambda)}_N(\theta)$ satisfies $|\hat{\theta}-\lambda|\leq \epsilon$ with probability at least $1-\delta$. As before, $G_K$ is the uniform grid with $K=\lceil {\frac{A\pi}{2\epsilon}}\rceil \leq \frac{A\pi}{\epsilon}$, which gives $\frac{1}{\kappa}=\frac{2K}{\pi}\leq \frac{2A}{\epsilon}$ and $2K\leq \frac{2A\pi}{\epsilon}$ and therefore justifies ($*$). Furthermore, we have $\kappa=\frac{\pi}{2K}\leq \frac{\epsilon}{A}\implies A\kappa\leq \epsilon\leq 1/T$. Therefore, our previously made assumption $A\kappa\leq 1/T$ was valid. 
\end{proof}

\begin{proof}[Proof of \cref{theorem:main}]
    For any window $p$ and any $N\in \mathbb{N}_{\geq1}$, the first step of \cref{alg:ldae} is to use a quantum computer to collect $N$ i.i.d.\ draws of $(m_i, Z_i)$ to construct the loss function
    \begin{equation}
        L(\theta)=\frac{1}{N}\sum^N_{i=1}\left(Z_i-\cos(2m_i\theta)\right)^2,
    \end{equation}
    which is identical to $L^{(\lambda)}_N(\theta)$ from \cref{def:empirical_loss}, since $Z_i$ is sampled from a distribution equivalent to $p_{m_i}^{(\lambda)}$. Since $\sigma \geq 1$ and $M \geq 1$, we have $T = \max(1, M/\sigma) \leq M$ and therefore $\epsilon \leq 1/M \leq 1/T$. Moreover, by \cref{remark:definitions} every $(b,\sigma)$-admissible window is $(b,\sigma,\sigma^2,\sigma^4,\sigma^6,\sigma^8)$-admissible, so \cref{lemma:main} applies.
    Since $T \geq M/\sigma$, we have $\sigma^2T^2N \geq M^2N$, and hence choosing $N$ such that
    \begin{equation}
        M^2N \;\geq\; \frac{4\sigma^2A^2C_9^2}{\epsilon^2}\log\left(\frac{2A\pi}{\epsilon\delta}\right)
    \end{equation}
    implies \cref{eq:lemma_cond} such that \cref{lemma:main} ensures that the minimizer $\hat{\theta}$, found by \cref{alg:ldae} through minimization of $L(\theta)$ over the uniform grid $G_K$ with $K=\lceil \frac{A\pi}{2\epsilon}\rceil$, satisfies $|\hat{\theta}-\lambda|\leq \epsilon$ with probability at least $1-\delta$. In particular, choosing $N$ such that 
    \begin{equation}
        N=\left\lceil \frac{4\sigma^2A^2C_9^2}{M^2\epsilon^2}\log\left(\frac{2A\pi}{\epsilon \delta} \right)\right\rceil
    \end{equation}
    is sufficient and implies $M^2N\in {\mathcal{O}}\left( \epsilon^{-2}\log (\epsilon^{-1}\delta^{-1})\right)$. Since $A$ and $C_9$ only depend on $b$, $\sigma$, and $C, C', C'', C'''$, which can all be bounded by powers of $\sigma$, we can conclude that the hidden constant factor only depends on $b$ and $\sigma$. Furthermore, with $\hat{\theta}=\lambda+e$ with $|e|\leq \epsilon$, we can convert the guarantee on $\hat{\theta}$ to a guarantee on the estimate returned by \cref{alg:ldae}, i.e. $\hat{a}=\sin^2(\hat{\theta})$ via
    \begin{align}
        |\hat{a}-a|&=|\sin^2(\lambda+e)-\sin^2\lambda|\\&=|\sin(e)\sin(2\lambda+e)|\\&=|\sin(e)\left(\sin(2\lambda)\cos(e)+\cos(2\lambda)\sin(e) \right)|\\
        &\leq |\sin(e)||\sin(2\lambda)\cos(e)|+\sin^2(e)|\cos(2\lambda)|\\
        &\leq \sin(2\lambda)|e|+e^2\\
        &\leq 2\sqrt{a(1-a)}\epsilon+\epsilon^2,
    \end{align}
    where in the last step we have used that 
    \begin{equation}
        \sin(2\lambda)=2\sin\lambda\cos\lambda = 2\sqrt{a}\sqrt{1-a}.
    \end{equation}
\end{proof}

\begin{proof}[Proof of \cref{cor:interpolation}]
    Define the uniform window $u_M:W_M\to[0,1]$ via $u_M(m)=1/(2M+1)$. Since $T=\max(1, M/\sigma)=M$ for $\sigma=1$, and 
    \begin{equation}
        u_M(m)+u_M(-m)=\frac{2}{2M+1}\geq \frac{2}{3M}=\frac{2/3}{T}
    \end{equation}
    for every $M\in\mathbb{N}_{\geq 1}$, the uniform window $u_M$ is $(2/3,1)$-admissible for every $M\in\mathbb{N}_{\geq 1}$. 

    Set $M:=\lfloor \epsilon^{-1+\beta}\rfloor$, which satisfies $M\in \mathbb{N}_{\geq 1}$ since $\epsilon\leq 1$ and $\beta\leq 1$. We then have $M\leq \epsilon^{-1+\beta}\leq \epsilon^{-1}\implies 1/M\geq \epsilon$. By \cref{theorem:main}, applied to $u_M$ with $K = \lceil A\pi/(2\epsilon)\rceil$, there exists a choice of $N$ for which $M^2N\in{\mathcal{O}}(\epsilon^{-2}\log(\epsilon^{-1}\delta^{-1}))$ and for which \cref{alg:ldae} returns, with probability at least $1-\delta$, an estimate $\hat{\theta}$ satisfying $|\hat{\theta}-\lambda|\leq \epsilon$ for every $\lambda\in[0,\pi/2]$. Consequently, $\hat{a}=\sin^2(\hat{\theta})$ satisfies \cref{eq:error_prop} for every $a\in[0,1]$. Since $\frac{1}{2}\epsilon^{-1+\beta}\leq M\leq \epsilon^{-1+\beta}$ (because $\lfloor x \rfloor \geq x/2$ for all $x\geq 1$), this is implied by 
    \begin{equation}
        N\in{\mathcal{O}}(\epsilon^{-2}M^{-2}\log(\epsilon^{-1}\delta^{-1}))={\mathcal{O}}(\epsilon^{-2\beta}\log(\epsilon^{-1}\delta^{-1})).
    \end{equation}
    The query count is upper bounded by $MN$, so \cref{alg:ldae} requires at most
    \begin{equation}
        MN\in{\mathcal{O}}(\epsilon^{-1+\beta}\epsilon^{-2\beta}\log(\epsilon^{-1}\delta^{-1}))={\mathcal{O}}(\epsilon^{-1-\beta}\log(\epsilon^{-1}\delta^{-1}))
    \end{equation}
    queries to $U$ and $U^\dagger$, while the maximum circuit depth is $M\leq \epsilon^{-1+\beta}\in \mathcal{O}(\epsilon^{-1+\beta})$. Finally, every circuit executed by \cref{alg:ldae} consists of powers of $G$ and, for even depths, one additional reflection around $I-2P$, applied to $\ket{\psi}$, followed by a measurement of $I-2P$ or $2\ket{\psi}\bra{\psi}-I$. It therefore requires neither ancilla qubits nor controlled Grover operations.  
\end{proof}

