To prove the stronger converse bound, we start with the following simple facts about entropy.
\begin{lemma}\label{lem_tailbound}
Let $p = (p_0,p_1,\dots,p_{n-1}) \in \R_+^n$ be a probability distribution with $p_0 \geq p_1 \geq \ldots p_{n-1}$, $r = 1- p_0$, and $w_i = p_i/r$ for all $i \in \{1,\ldots,n-1\}$. Then
\begin{enumerate}[(i)]
\item $ H(p) = h(p_0) + rH(w) $ and for $\tau = \sum_{i=2}^{n-1} p_i$ we have $H(p) \geq h(p_0) + rh(\tau/r)$ \label{it_entropy1}
\item if $p_i \leq \frac{1}{2}$ for all $i$ we have $H(p) \geq 1$. \label{it_entropy2}
\end{enumerate}
\end{lemma}
\begin{proof}
We start by proving the statement~\eqref{it_entropy1}.
Note that $1-p_0 = \sum_{i=1}^{n-1} p_i$ and therefore $w=(w_1,\ldots,w_{n-1}) \in \R_+^{n-1}$ is a probability distribution. Thus, we have
\begin{align}
H(p)
&= - p_0 \log p_0 - \sum_{i=1}^{n-1} p_i \log p_i \\
&=- p_0 \log p_0 - \sum_{i=1}^{n-1} (r w_i) \log (r w_i) \\
&=- p_0 \log p_0 - r\log r\sum_{i=1}^{n-1} w_i -r\sum_{i=1}^{n-1} w_i  \log w_i \\
&= h(p_0) + r H(w) \, .
\end{align}
The second statement of~\eqref{it_entropy1} follows from the first by grouping $w_2,w_3,\dots,w_{n-1}$ into one event of probability $\tau/r$. Then define the probabilities $v_i = p_i/\tau$ for $i\geq 2$. A second application of the previous calculation gives
\begin{equation}
    H(w) = h(\tau/r) + \frac{\tau}{r} H(v) \geq h(\tau/r) \, .
\end{equation}

Thus, it remains to prove~\eqref{it_entropy2}. Note that $p_i \leq \frac{1}{2}$ implies $-\log p_i \geq 1$. Therefore
\begin{align}
H(p) 
= -\sum_{i=0}^{n-1}p_i \log p_i
\geq \sum_{i=0}^{n-1} p_i
=1 \, .
\end{align}
\end{proof}

For $r=1-p_0$ let $A := \sin(\phi/2)\frac{2p_0-1}{2}$ and $B:= A(D-3)+r(D-2)$. Furthermore, let
    \begin{equation} \label{eq_tau_opt}
\tau_D(p_0) := 2\, \frac{B - \sqrt{B^2-(D-1)^2A^2}}{(D-1)^2} \, .
    \end{equation}
The heart of the converse bound is built on the following lemma. The first steps are similar to~\cite{SG11}.
\begin{lemma}\label{lem_conv_core}
    The resource state of every deterministic SEP implementation, hence every LOCC teleportation, satisfies
    \begin{equation} \label{eq_strong_converse_feasible}
        \sin(\phi/2)(2p_0-1) \leq 2\sum_{1\leq i < j}^{D-1} \sqrt{p_i p_j} \, .
    \end{equation}
\end{lemma}
\begin{proof}
    Every LOCC protocol is included in the class of SEP channels~\cite{LOCC14}, which we can characterize via product Kraus operators $K_k = E_k \otimes F_k$ satisfying
\begin{equation} \label{eq_kraus1}
    \sum_k K_k^\dagger K_k = \id \, .
\end{equation}
Here, $E_k : AA' \mapsto A$ and $F_k :BB' \mapsto B$.
For a deterministic implementation of $U_\phi$, each of those operators has to satisfy
\begin{equation} \label{eq_kraus2}
    K_k ( \id_{AB} \otimes \ket{\psi_p}_{A'B'}) = \alpha_k U_\phi\,,
\end{equation}
where 
\begin{equation}
    \ket{\psi_p}_{A'B'} = \sum_{i=0}^{D-1} \sqrt{p_i}\ket{ii}_{A'B'}
\end{equation}
is the resource state.
The scalar $\alpha_k$ can depend on $k$, but not on the input. Since $U_\phi$ is unitary \cref{eq_kraus1,eq_kraus2} imply
\begin{equation}\label{eq_kraus3}
    \sum_k |\alpha_k|^2 = 1 \, .
\end{equation}
In the following, we will absorb the phase into each Kraus operator so that $\alpha_k \geq 0$.
Next, let us express $U_\phi$ as
\begin{equation}
    U_\phi = \sum_{a,b=0}^1 \hat{U}_{ab} \ketbra{a}{a}_A \otimes \ketbra{b}{b}_B \qquad \textnormal{with} \qquad \hat{U} = \begin{pmatrix}
        1 & 1 \\
        1 & \ee^{\ci\phi}
    \end{pmatrix} \, .
\end{equation}
Note that, $\hat{U}$ is invertible since $\det \hat{U} = \ee^{\ci \phi}-1 \neq 0$.\footnote{Without loss of generality we assume $\phi \in (0,\pi]$, since the case $\phi=0$ is trivial anyway.}
For each $k$ we use the basis of $\ket{a}_A$ and $\ket{b}_B$ to sandwich~\cref{eq_kraus2} yielding
\begin{align}
     \bra{a}_A\bra{b}_B (E_k\otimes F_k) ( \ket{a}_A\ket{b}_B \otimes \ket{\psi_p}_{A'B'}) = \alpha_k \hat{U}_{ab} \, .
\end{align}
Writing $\ket{\psi_p}_{A'B'}$ in its Schmidt decomposition, we get
\begin{equation}\label{eq_consist1}
    \sum_{i=0}^{D-1} \sqrt{p_i} \, \bra{a}_A E_k \ket{a}_A \ket{i}_{A'} \, \bra{b}_B F_k \ket{b}_B \ket{i}_{B'} = \alpha_k \hat{U}_{ab} \, .
\end{equation}
Defining coefficients 
\begin{equation}
    (e_k)_{ai}:=  \bra{a}_A E_k \ket{a}_A \ket{i}_{A'}  \qquad \textnormal{and} \qquad 
    (f_k)_{bi}:= \bra{b}_B F_k \ket{b}_B \ket{i}_{B'}
\end{equation}
we can write~\cref{eq_consist1} as
\begin{equation}\label{eq_consist2}
    \sum_{i=0}^{D-1} \sqrt{p_i} \, (e_k)_{ai} \, (f_k)_{bi} = \alpha_k \hat{U}_{ab} \, ,
\end{equation}
or if we define the diagonal matrix $\Psi = \diag(\sqrt{p_0},\sqrt{p_1},\sqrt{p_2},\dots)$ as
\begin{equation}\label{eq_matrix}
    \hat{E}_k \Psi \hat{F}_k^T = \alpha_k \hat{U} \, .
\end{equation}
Here, $\hat{E}_k, \hat{F}_k \in \mathbb{C}^{2\times D}$ and we can write them as matrices whose columns are two-dimensional vectors
\begin{equation}
    \hat{E}_k = 
    \begin{pmatrix}| & &| \\
        \mathbf{e}_{k,0} & \cdots & \mathbf{e}_{k,D-1} \\
        | & &|
    \end{pmatrix} \qquad \textnormal{and} \qquad  
    \hat{F}_k = 
    \begin{pmatrix}| & &| \\
        \mathbf{f}_{k,0} & \cdots & \mathbf{f}_{k,D-1} \\
        | & &|
    \end{pmatrix} \, .
\end{equation}
With this, we can write~\cref{eq_matrix} as
\begin{equation}\label{eq_consist1_vec}
    \sum_{i=0}^{D-1} \sqrt{p_i} \, \mathbf{e}_{k,i}\mathbf{f}_{k,i}^T = \alpha_k \hat{U} \, .
\end{equation}

Let us now take the determinant of both sides of~\cref{eq_matrix}. This gives
\begin{equation}
    \det (\alpha_k \hat{U}) = \alpha_k^2 \det \hat{U} 
\end{equation}
and on the other side using Binet-Cauchy~\cite[Section~0.8.7]{Horn_Johnson_1985}
\begin{equation}
    \det ( \hat{E}_k \Psi \hat{F}_k^T) = \sum_{i<j} \sqrt{p_i p_j}  \det(\mathbf{e}_{k,i}\, \mathbf{e}_{k,j}) \det(\mathbf{f}_{k,i}\, \mathbf{f}_{k,j}) \, .
\end{equation}
For sake of notation, define 
\begin{equation}
    \Lambda_{ij}^k :=\det(\mathbf{e}_{k,i}\, \mathbf{e}_{k,j}) \det(\mathbf{f}_{k,i}\, \mathbf{f}_{k,j}) 
\end{equation}
If we now sum over $k$, we get
\begin{equation}\label{eq_conv_det1}
    \sum_k \alpha_k^2 \det \hat{U}  \overset{\textnormal{\Cshref{eq_kraus3}}}{=}  \det \hat{U} = \sum_{i<j} \sqrt{p_i p_j} \, \sum_k \Lambda_{ij}^k \, .
\end{equation}

Starting from~\cref{eq_consist1_vec}, we can also define the quantity $M(t)$
\begin{equation}
M(t) 
:= t  \sqrt{p_0} \, \mathbf{e}_{k,0}\mathbf{f}_{k,0}^T +\sum_{i=1}^{D-1} \sqrt{p_i} \mathbf{e}_{k,i}\mathbf{f}_{k,i}^T \, ,
\end{equation}
which for $t=1$ again gives~\cref{eq_consist1_vec}. Calculating the determinant of this expression then gives analogously as above
\begin{equation}
    \det M(t) = t \sum_{j=1}^{D-1}
 \sqrt{p_0 p_j}\, \Lambda^k_{0j} + \sum_{1\leq i < j \leq D-1} \sqrt{p_i p_j}\,  \Lambda^k_{ij} \, .
\end{equation}
For $2\times 2$ matrices, we have
\begin{equation}
    \frac{\di }{\di t} \det M(t) = \tr[\adj(M(t))M'(t)]
\end{equation}
where $\adj(M)$ denotes the adjugate of $M$.
Evaluating this expression at $t=1$ with $M'(t)= \sqrt{p_0} \, \mathbf{e}_{k,0}\mathbf{f}_{k,0}^T $
gives
\begin{equation}\label{eq_t0_equation}
    \sum_{j=1}^{D-1} \sqrt{p_0 p_j}\, \Lambda^k_{0j} =\sqrt{p_0} \, \tr[\adj(\alpha_k \hat{U})  \mathbf{e}_{k,0}\mathbf{f}_{k,0}^T]
\end{equation}
For $2\times 2$ matrices, the adjugate satisfies $\adj(\alpha_k \hat{U}) = \alpha_k  \adj( \hat{U}) = \alpha_k \det(\hat{U}) \hat{U}^{-1}$ and, therefore, we get
\begin{equation}\label{eq_conv_det}
     \sum_{j=1}^{D-1}\sqrt{p_0 p_j}\, \Lambda^k_{0j} = \sqrt{p_0} \det (\hat{U}) \tr[\hat{U}^{-1} \alpha_k\mathbf{e}_{k,0}\mathbf{f}_{k,0}^T]\, .
\end{equation}
To proceed, we return to~\cref{eq_kraus1}.
Multiply it on the left by $\id_{AB} \otimes \bra{\psi_p}_{A'B'}$ to get
\begin{align}
\id_{AB} \otimes \bra{\psi_p}_{A'B'} 
\overset{\textnormal{\Cshref{eq_kraus1}}}{=} \sum_k \id_{AB} \otimes \bra{\psi_p}_{A'B'} K_k^\dagger K_k 
\overset{\textnormal{\Cshref{eq_consist1}}}{=} \sum_k \alpha_k U^\dagger_\phi K_k  \, .
\end{align}
Another multiplication with $U_\phi$ gives
\begin{equation}
     \sum_k \alpha_k  K_k  = (U_\phi)_{AB} \otimes \bra{\psi_p}_{A'B'} \, .
\end{equation}
Now we sandwich this equation with basis vectors $\ket{a}_A,\ket{b}_B,\ket{ij}_{A'B'}$ again to obtain
\begin{align}
    \sum_k \alpha_k \, \bra{a}_A\bra{b}_B \, K_k \, ( \ket{a}_A\ket{b}_B \otimes \ket{ij}_{A'B'}) &= \bra{a}_A\bra{b}_B(U_\phi)_{AB} \ket{a}_A\ket{b}_B  \,\braket{\psi_p|ij}_{A'B'} \, ,
\end{align}  
which equivalently can be expressed as
\begin{align}
    \sum_k \alpha_k (e_k)_{ai} (f_k)_{bj} &= \hat{U}_{ab} \sqrt{p_i} \, \delta_{ij}\, .\label{eq_completeness}
\end{align}
Choosing $i=j=0$, this gives
\begin{equation}
    \sum_k \alpha_k (e_k)_{a0} (f_k)_{b0} = \sqrt{p_0} \hat{U}_{ab} 
\end{equation}
or as matrices with the vector notation from before
\begin{equation}\label{eq_converse3}
    \sum_k \alpha_k  \,\mathbf{e}_{k,0} \mathbf{f}_{k,0}^T = \sqrt{p_0} \hat{U} \, .
\end{equation}
Going back to~\cref{eq_conv_det}, we note that summing over $k$ gives
\begin{align}
    \sum_{j=1}^{D-1}\sqrt{p_0 p_j}\, \sum_k\Lambda^k_{0j} &=  \sqrt{p_0} \det \hat{U} \, \tr[\hat{U}^{-1}\sum_k\alpha_k\mathbf{e}_{k,0} \mathbf{f}_{k,0}^T] \\
    \overset{\textnormal{\Cshref{eq_converse3}}}&{=} \sqrt{p_0} \det \hat{U}  \,\tr[\hat{U}^{-1} \, \sqrt{p_0} \hat{U} ]  \\
    &= p_0 \det \hat U \tr[\id_2] \\
    &= 2 p_0 \det \hat{U}\, .
\end{align}
Subtracting this term from~\cref{eq_conv_det1} then gives
\begin{equation}\label{eq_conv_det3}
    \sum_{1\leq i< j}^{D-1} \sqrt{p_ip_j}\sum_k \Lambda_{ij}^k = (1-2p_0) \det \hat U \, .
\end{equation}
To finish our proof, we need to bound $\sum_k \Lambda_{ij}^k $.
To do so, we expand it into scalar terms
\begin{align}\label{eq_conv_lambda}
     \Lambda_{ij}^k &= \det(\mathbf{e}_{k,i}\, \mathbf{e}_{k,j}) \det(\mathbf{f}_{k,i}\, \mathbf{f}_{k,j}) \\
     &= ((e_k)_{0i}  \,(f_k)_{0i})  ((e_k)_{1j} \, (f_k)_{1j}) -  ((e_k)_{0i}  \,(f_k)_{1i})  ((e_k)_{1j} \, (f_k)_{0j}) \\
     & \qquad -((e_k)_{1i}  \,(f_k)_{0i})  ((e_k)_{0j} \, (f_k)_{1j}) + ((e_k)_{1i}  \,(f_k)_{1i})  ((e_k)_{0j} \, (f_k)_{0j}) \, .
\end{align}
Furthermore, we note that~\cref{eq_kraus1} implies
\begin{equation}
    \sum_k \norm{E_k \ket{ai}_{AA'}}^2 \norm{F_k \ket{bj}_{BB'}}^2 = 1 
\end{equation}
by multiplying $\ket{ai}_{AA'}\ket{bj}_{BB'}$ from both sides.
Projecting $E_k \ket{ai}_{AA'}$ onto $\ket{a}_A$ and respectively with  $F_k \ket{bj}_{BB'}$ onto $\ket{b}_B$ can only decrease their norms, so this implies
\begin{equation}\label{eq_conv_sumbound}
    \sum_k |(e_k)_{ai}|^2 |(f_k)_{bj}|^2 \leq 1 \, .
\end{equation}
Using Cauchy-Schwarz and~\cref{eq_conv_sumbound}, we can bound the first term in~\cref{eq_conv_lambda} by
\begin{equation}
    \sum_k |((e_k)_{0i}  \,(f_k)_{0i})  ((e_k)_{1j} \, (f_k)_{1j})|
    \leq \sqrt{\sum_k |(e_k)_{0i}|^2 |(f_k)_{0i}|^2} \sqrt{\sum_k |(e_k)_{1j}|^2 |(f_k)_{1j}|^2} \leq 1 \, .
\end{equation}
The same argument also applies to the other three terms. Therefore,
\begin{equation} \label{eq_Lambda_bound}
    \sum_k |\Lambda^k_{ij}| \leq 4 .
\end{equation}
Now using the triangle inequality we get from~\cref{eq_conv_det3}
\begin{equation}
    (2p_0-1) \, |\det \hat U|  \leq \sum_{1\leq i<j}^{D-1} \sqrt{p_i p_j} \sum_k |\Lambda^k_{ij}| \overset{\textnormal{\Cshref{eq_Lambda_bound}}}{\leq} 4\sum_{1\leq i<j}^{D-1}  \sqrt{p_i p_j} \, .
\end{equation}
Together with $|\det \hat{U}| = 2 \sin(\phi/2)$, this completes the proof.
\end{proof}

\begin{lemma}\label{lem_cauchy} Let $p = (p_0,p_1,\dots,p_{D-1}) \in \R_+^D$ be a probability distribution with $p_0 \geq p_1 \geq \ldots p_{D-1}$, $r = 1- p_0$, and $\tau = \sum_{i=2}^{D-1}p_i$. Then
    \begin{equation}
        \sum_{1\leq i< j}^{D-1} \sqrt{p_i p_j}  \leq  \sqrt{(r-\tau)(D-2)\tau} + \frac{D-3}{2}\tau =: f(\tau) \, .
    \end{equation}
    Moreover, $0 \leq \tau \leq \frac{(D-2)r}{D-1}$ and $f$ is increasing on this interval.
\end{lemma}
\begin{proof}
    Separating the $p_1$ term, we get
    \begin{equation} \label{eq_lem_cauchy1}
         \sum_{1\leq i< j}^{D-1} \sqrt{p_i p_j} =  \sqrt{p_1} \sum_{i=2}^{D-1} \sqrt{p_i} +  \sum_{2\leq i< j}^{D-1} \sqrt{p_i p_j} \, .
    \end{equation}
    Cauchy-Schwarz then gives
    \begin{equation} \label{eq_up_tau_1}
        \sum_{i=2}^{D-1} \sqrt{p_i} \leq \sqrt{(D-2)\sum_{i=2}^{D-1} p_i } = \sqrt{(D-2)\tau} \, .
    \end{equation}
    Consider now 
    \begin{equation}
        \left( \sum_{i=2}^{D-1} \sqrt{p_i} \right)^2 = \sum_{i=2}^{D-1} p_i + 2 \sum_{2\leq i < j} \sqrt{p_i p_j} = \tau + 2 \sum_{2\leq i < j} \sqrt{p_i p_j} \, .
    \end{equation}
    Using Cauchy-Schwarz on the first term and rearranging gives us
    \begin{equation}
        \sum_{2\leq i < j} \sqrt{p_i p_j} \leq  \frac{D-3}{2} \tau\, . \label{eq_up_tau_2}
    \end{equation}
    Together, noting that $p_1 = r-\tau$, we can rewrite~\cref{eq_lem_cauchy1} as
    \begin{equation}
         \sum_{1\leq i< j}^{D-1} \sqrt{p_i p_j}  
         \overset{\textnormal{\Cshref{eq_lem_cauchy1,eq_up_tau_1,eq_up_tau_2}}}{\leq}  \sqrt{(r-\tau)(D-2)\tau} + \frac{D-3}{2}\tau \, .
    \end{equation}


Since $p_i \leq p_1 = r-\tau $ for all $i\geq2$, this implies $\tau \leq (D-2)(r-\tau)$, which rearranges to
$\tau \leq \frac{(D-2)r}{D-1}$. Taking the derivative of the defined function $f$, one can check that $f'(\tau)\geq0$ on the interval $\tau\in[0,\frac{(D-2)r}{D-1}]$.
\end{proof}

\begin{lemma}\label{lem_taubound}
Let $p \in \R_+^D$ be a resource spectrum satisfying~\cref{eq_strong_converse_feasible} with $1/2 \leq p_0 \leq q$, $r = 1- p_0$, and $\tau = \sum_{i=2}^{D-1}p_i$. Then,
    \begin{equation} \label{eq_bound_tau}
        \tau \geq \tau_D(p_0)\, , 
    \end{equation}
    where $\tau_D(p_0)$ is defined in~\cref{eq_tau_opt}.
\end{lemma}
\begin{proof}
We start by noting that 
    \begin{equation}
        \sin(\phi/2)\frac{2p_0-1}{2} 
        \overset{\textnormal{\Cshref{lem_conv_core}}}{\leq} \sum_{1\leq i < j}^{D-1} \sqrt{p_i p_j}  
        \overset{\textnormal{\Cshref{lem_cauchy}}}{\leq} f(\tau) \, .
    \end{equation}
    By~\cref{lem_cauchy}, $f$ is increasing on $[0,\frac{(D-2)r}{D-1}]$ and takes values in $[f(0)=0,f(\frac{D-2}{D-1}r)=\frac{D-2}{2}r]$. So, there is one $\tau_*$ such that
    \begin{equation} \label{eq_def_A}
        f(\tau_*) = \sin(\phi/2) \frac{2p_0-1}{2} = A
    \end{equation}
    or equivalently
    \begin{equation}
        \sqrt{(r-\tau_*)(D-2)\tau_*} = A - \frac{D-3}{2} \tau_* \, .
    \end{equation}
This can be reformulated as the following quadratic equation
    \begin{align} \frac{(D-1)^2}{4}\tau_*^2 - \big(A(D-3)+r(D-2) \big)\tau_* + A^2=0 \, .
    \end{align}
    Solving it for the smaller root (it is the one that vanishes as $A\to0$) yields
    \begin{equation}
        \tau_* 
        = 2\, \frac{B - \sqrt{B^2-(D-1)^2A^2}}{(D-1)^2} 
        \overset{\textnormal{\Cshref{eq_tau_opt}}}{=} \tau_D(p_0) \, ,
    \end{equation}
    where $B = A(D-3)+r(D-2)$. Together, we have
    \begin{equation}
        f(\tau_*) \overset{\textnormal{\Cshref{eq_def_A}}}{=} A \leq f(\tau)
    \end{equation}
    and monotonicity of $f$ implies $\tau\geq \tau_*$.
\end{proof}

\begin{theorem}\label{thm_tightestconverse}
    For $1/2\leq p_0 \leq q<1$, let $\tau_D(p_0)$ be as defined in~\cref{eq_tau_opt}. Every rank-D spectrum satisfying~\cref{eq_strong_converse_feasible} fulfills
    \begin{align} \label{eq_converse_stronger}
        H(p) \geq h(p_0) + (1-p_0)h\left(\frac{\tau_D(p_0)}{1-p_0}\right) \, .
    \end{align}
\end{theorem}
\begin{proof}
    Let $r=1-p_0$ and $\tau$ be the mass outside the two largest probabilities. By~\cref{lem_taubound}, $\tau \geq \tau_D(p_0)$. 
    First, suppose $\tau \leq r/2$. Then both $\tau_D/r$ and $\tau/r$ are in $[0,1/2]$. The binary entropy increases on this interval.
    Using \cref{lem_tailbound},
    \begin{equation}
        H(p)\geq h(p_0) + rh\left(\frac{\tau}{r}\right) \geq h(p_0) + r h\left(\frac{\tau_D(p_0)}{r}\right) \, .
    \end{equation}

    Now suppose $\tau > r/2$. Then $p_1=r-\tau <r/2$ and therefore for all $i\geq2$, $p_i \leq p_1\leq r/2$. Thus, every $w_i = p_i/r$ is smaller than $1/2$. By~\cref{lem_tailbound}
     we then have $H(w)\geq 1$ and therefore
     \begin{equation}
         H(p) = h(p_0) + rH(w)\geq h(p_0) + r \, .
     \end{equation}
     Since $h(x)\leq 1$, this finishes the proof.
\end{proof}

Let $\phi \in [0,\pi]$ and $U_{\phi}=\diag(1,1,1,\ee^{\ci \phi})$ be a controlled-phase gate. Any gate teleportation protocol for $U_{\phi}$ with a resource state $\ket{\psi}_{A'B'}$ of Schmidt rank $D\geq 3$ must fulfill
\begin{align}
H(A')_\psi 
\overset{\textnormal{\Cshref{thm_tightestconverse}}}{\geq} \min_{p_0 \in [1/2,\frac{1}{1+\sin(\phi/2)}]} \Big \{  h(p_0) + (1-p_0)h\left(\frac{\tau_D(p_0)}{1-p_0}\right) \Big \} \, . \label{eq_stronger_converse}
\end{align}
Note that for a resource state with $p_0 <1/2,$~\cref{lem_tailbound} yields $H(p) \geq 1,$ which is clearly bigger than the right-hand side of~\cref{eq_stronger_converse}. 

